{"hypotheses": [
  {
    "name": "Organizational Capital Defensive Growth",
    "mechanism": "Stocks with high organizational capital ('OrgCap') combined with low short interest ('ShortInterest') are likely to represent firms with persistent competitive advantages and less information-based shorting pressure. Adding a negative weight to 'MRreversal' (medium-run reversal) further concentrates on firms that exhibit sustained improvement, filtering out mean-reverting underperformers. The composite should outperform its components by capturing durable intangible-driven growth with a risk-mitigating tilt.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "ShortInterest"},
        {"weight": -0.5, "primitive": "MRreversal"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Long-Term Investment Quality Distress Hedge",
    "mechanism": "Firms with high cumulative capex growth over three years ('grcapx3y') but low debt issuance ('DebtIssuance') are investing for long-term growth without over-relying on leverage. Subtracting 'OScore' (distress risk) emphasizes avoidance of financially fragile firms. This composite should create a unique risk/return profile unavailable from the primitives by isolating healthy, growth-oriented capital allocators who avoid financial distress.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "grcapx3y"},
        {"weight": 1.0, "primitive": "DebtIssuance"},
        {"weight": -1.0, "primitive": "OScore"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Controversy-Resilient Intangible Value",
    "mechanism": "Firms with high intangible-adjusted book-to-market ('IntanBM') that also see an increase in analyst coverage ('ChNAnalyst') and a negative sentiment from excluded expenses ('ExclExp') can represent underappreciated but improving intangible asset plays that are resilient to negative accounting surprises. The composite capitalizes on mispricings in under-covered, controversial firms whose intangible value is being slowly recognized.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": 0.5, "primitive": "ChNAnalyst"},
        {"weight": -0.5, "primitive": "ExclExp"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Customer Momentum-Driven Profitability Spread",
    "mechanism": "Firms with high customer momentum ('iomom_cust') that also exhibit strong cash-based operating profitability ('CBOperProf'), but low bid-ask spreads ('BidAskSpread'), are firms leveraging strong demand fundamentals and operational efficiency without liquidity penalty. The composite should outperform by combining supply-chain strength with genuine profitability and liquidity, filtering out high transaction cost stocks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 1.0, "primitive": "CBOperProf"},
        {"weight": -0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Analyst Skepticism with Deferred Revenue Buffer",
    "mechanism": "Stocks with negative EPS forecast revisions ('AnalystRevision'), but rising deferred revenue ('DelDRC'), and low net external financing ('XFIN'), may be undervalued if the increase in deferred revenue signals future performance being underestimated by analysts. This composite captures a behavioral inefficiency where pessimistic analyst sentiment misses business model resilience.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "DelDRC"},
        {"weight": -0.5, "primitive": "XFIN"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 21
  },
  {
    "name": "Dividend Omission Contrarian Quality",
    "mechanism": "Firms omitting dividends ('DivOmit') but with high gross profits to assets ('GP'), and low idiosyncratic volatility ('IdioVolAHT'), may face overdone pessimism by yield-seeking investors. The composite focuses on quality companies that temporarily suspend dividends, betting on subsequent revaluation as the underlying profitability persists and volatility stays controlled.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DivOmit"},
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -1.0, "primitive": "IdioVolAHT"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "DivYieldST", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 28
  },
  {
    "name": "Option Sentiment and Operating Momentum Squeeze",
    "mechanism": "Firms with a sharp increase in call option volume ('dVolCall'), high change in asset turnover ('ChAssetTurnover'), but low probability of informed trading ('ProbInformedTrading'), may be experiencing a positive feedback loop between real business improvements and retail sentiment, but without the risks associated with informed traders. The composite targets underappreciated operating momentum that is only just being recognized in the options market.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "dVolCall"},
        {"weight": 1.0, "primitive": "ChAssetTurnover"},
        {"weight": -1.0, "primitive": "ProbInformedTrading"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "MaxRet", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Supply Chain Tightness with Low Earnings Manipulation",
    "mechanism": "Firms with high supplier momentum ('iomom_supp') but low abnormal accruals ('AbnormalAccruals'), and low change in capital investment ('ChInvIA'), are likely benefiting from upstream demand without relying on aggressive accounting or capex manipulation. The composite captures stocks with strong supply chain positioning and real, not engineered, earnings quality.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": -1.0, "primitive": "AbnormalAccruals"},
        {"weight": -0.5, "primitive": "ChInvIA"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "Accruals", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.68,
    "expected_decay_half_life_months": 20
  }
]}
